/////////////////////////////////////////////////////////////////////////////
// cam_fps.v
//
// Measures the real CAMERA frame rate.
//
// The FPS that the OSD used to show was counted from the video output VSYNC,
// which is generated by cvo_axi and therefore always 60Hz, no matter how fast
// the sensor actually runs.  This module counts the sensor VSYNC in the MIPI
// pixel clock domain instead and hands the result over to the display clock
// domain through a single toggling bit (no multi bit CDC problem).
//
// 1 second time base = 148500000 cycles of the display pixel clock.
/////////////////////////////////////////////////////////////////////////////
module cam_fps
#(
	parameter integer DISP_TICKS_PER_SEC = 148500000
)
(
	input				i_cam_clk,
	input				i_cam_arstn,
	input				i_cam_vs,		// sensor VSYNC, active high

	input				i_disp_clk,		// 148.5 MHz
	input				i_disp_arstn,

	output reg [6:0]	o_fps
);

//===========================================================================
// camera domain: one toggle per frame
//===========================================================================
reg		r_cam_vs_d;
reg		r_tgl;

always @(posedge i_cam_clk or negedge i_cam_arstn)
begin
	if (!i_cam_arstn)
	begin
		r_cam_vs_d	<= 1'b0;
		r_tgl		<= 1'b0;
	end
	else
	begin
		r_cam_vs_d	<= i_cam_vs;
		if (i_cam_vs && !r_cam_vs_d)
			r_tgl	<= ~r_tgl;
	end
end

//===========================================================================
// display domain
//===========================================================================
reg	[2:0]	r_sync;

always @(posedge i_disp_clk or negedge i_disp_arstn)
begin
	if (!i_disp_arstn)
		r_sync	<= 3'd0;
	else
		r_sync	<= {r_sync[1:0], r_tgl};
end

wire	w_frame_ev	= r_sync[2] ^ r_sync[1];	// one pulse per camera frame

reg	[27:0]	r_sec;
reg	[6:0]	r_frames;

always @(posedge i_disp_clk or negedge i_disp_arstn)
begin
	if (!i_disp_arstn)
	begin
		r_sec		<= 28'd0;
		r_frames	<= 7'd0;
		o_fps		<= 7'd0;
	end
	else if (r_sec == DISP_TICKS_PER_SEC-1)
	begin
		r_sec		<= 28'd0;
		o_fps		<= r_frames;
		r_frames	<= w_frame_ev ? 7'd1 : 7'd0;
	end
	else
	begin
		r_sec		<= r_sec + 1'b1;
		if (w_frame_ev)
			r_frames	<= r_frames + 1'b1;
	end
end

endmodule
